import React, { forwardRef, MouseEventHandler, PropsWithChildren } from "react";
import clsx from "clsx";
import { IconButton as IconButtonStyles } from "@airbus/styles";
import { createUseStyles } from "../../lib/styling";
import { CommonProps } from "../helperTypes";

type Props = PropsWithChildren<{
  /**
   * Pass true to disable the button
   * @default false
   */
  disabled?: boolean;
  /** Button click handler */
  onClick?: MouseEventHandler<HTMLButtonElement>;
  /** mouse down handler */
  onMouseDown?: MouseEventHandler<HTMLButtonElement>;
  /** Toggle button and set aria-pressed accordingly */
  pressed?: boolean;
  /**
   * The size of the button<br />
   * **Deprecated:** `extra-small` and `extra-large`
   * @default medium
   */
  size?: "xsmall" | "small" | "medium" | "large" | "xlarge";
  /**
   * The variant of the button
   * @default secondary
   */
  variant?:
    | "primary"
    | "secondary"
    | "ghost"
    | "ghostNegative"
    | "success"
    | "warning"
    | "error";
}>;

export type IconButtonProps = Props & CommonProps;

const useStyles = createUseStyles(IconButtonStyles, "iconbutton");

export const IconButton = (
  props: IconButtonProps,
  ref: React.Ref<HTMLButtonElement>
) => {
  const { variant, size, className, children, pressed, ...rest } = props;
  const classes = useStyles();

  return (
    <button
      type="button"
      ref={ref}
      className={clsx(
        className,
        classes.root,
        variant && classes[`_${variant}`],
        size && classes[`_${size}`]
      )}
      aria-pressed={pressed}
      {...rest}
    >
      {children}
    </button>
  );
};

export default forwardRef<HTMLButtonElement, IconButtonProps>(IconButton);
